1: //! Cyclic XOR de-scrambling and keystream application engine.
2: //!
3: //! Provides zero-allocation in-place de-scrambling (`descramble_in_place`), destination-slice
4: //! de-scrambling (`descramble_slice`), and allocating vector de-scrambling (`descramble_to_vec`)
5: //! for scrambled DJI record payloads.
6: 
7: use crate::crypto::crc64::derive_key;
8: use crate::error::FlightReaderError;
9: 
10: /// De-scrambles (or scrambles) `buf` in-place by cyclically applying the 8-byte `key`.
11: ///
12: /// Because XOR is an involutive operation ($A \oplus K \oplus K = A$), this function
13: /// is self-inverse: applying it twice with the same key restores the original bytes.
14: ///
15: /// Each byte `buf[i]` is mutated as `buf[i] ^= key[i % 8]`.
16: pub fn descramble_in_place(buf: &mut [u8], key: [u8; 8]) {
17:     for (i, b) in buf.iter_mut().enumerate() {
18:         *b ^= key[i % 8];
19:     }
20: }
21: 
22: /// De-scrambles (or scrambles) `src` into destination buffer `dst` using the cyclic 8-byte `key`.
23: ///
24: /// Returns `Ok(())` on success.
25: ///
26: /// # Errors
27: ///
28: /// Returns [`FlightReaderError::BufferOverflow`] if `dst.len() < src.len()`.
29: pub fn descramble_slice(src: &[u8], dst: &mut [u8], key: [u8; 8]) -> Result<(), FlightReaderError> {
30:     if dst.len() < src.len() {
31:         return Err(FlightReaderError::BufferOverflow {
32:             required: src.len(),
33:             capacity: dst.len(),
34:         });
35:     }
36: 
37:     for (i, (&s, d)) in src.iter().zip(dst.iter_mut()).enumerate() {
38:         *d = s ^ key[i % 8];
39:     }
40: 
41:     Ok(())
42: }
43: 
44: /// De-scrambles (or scrambles) `src` into a newly allocated [`Vec<u8>`] using cyclic 8-byte `key`.
45: #[must_use]
46: pub fn descramble_to_vec(src: &[u8], key: [u8; 8]) -> Vec<u8> {
47:     let mut out = Vec::with_capacity(src.len());
48:     for (i, &b) in src.iter().enumerate() {
49:         out.push(b ^ key[i % 8]);
50:     }
51:     out
52: }
