1: //! DJI `.DAT` blackbox binary frame parsing and stream iterator.
2: //!
3: //! Provides zero-allocation parsing of `.DAT` binary telemetry frames,
4: //! payload extraction, and a resilient synchronization iterator for scanning
5: //! corrupted or noisy raw streams.
6: 
7: use crate::dat::checksum;
8: use crate::error::{FlightReaderError, Result};
9: 
10: /// Synchronization magic byte for all DJI `.DAT` blackbox frames (`0x55` / `85` decimal).
11: pub const DAT_MAGIC: u8 = 0x55;
12: 
13: /// Length of the fixed frame header in bytes (Magic, Length, Sequence, PayloadID, Timestamp).
14: pub const HEADER_LEN: usize = 9;
15: 
16: /// The checksum verification algorithm utilized by a `.DAT` telemetry frame.
17: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
18: pub enum DatChecksumType {
19:     /// 16-bit CCITT checksum (2 bytes). Used by standard sensor frames (IMU, GPS, Battery).
20:     Crc16,
21:     /// 32-bit IEEE 802.3 checksum (4 bytes). Used by extended multi-sector frames.
22:     Crc32,
23: }
24: 
25: impl DatChecksumType {
26:     /// Returns the length of the checksum field in bytes (2 for CRC16, 4 for CRC32).
27:     #[inline]
28:     pub const fn checksum_len(&self) -> usize {
29:         match self {
30:             DatChecksumType::Crc16 => 2,
31:             DatChecksumType::Crc32 => 4,
32:         }
33:     }
34: 
35:     /// Returns the minimum physical frame length in bytes for this checksum type
36:     /// (9-byte header + checksum length).
37:     #[inline]
38:     pub const fn min_frame_len(&self) -> usize {
39:         HEADER_LEN + self.checksum_len()
40:     }
41: }
42: 
43: /// A zero-allocation borrowed view of a parsed DJI `.DAT` blackbox telemetry frame.
44: #[derive(Debug, Clone, PartialEq, Eq)]
45: pub struct DatFrame<'a> {
46:     /// Synchronization magic byte (must be `0x55`).
47:     pub magic: u8,
48:     /// Total frame length in bytes including header, payload, and checksum.
49:     pub length: u8,
50:     /// Frame sequence counter or sub-header flag.
51:     pub sequence: u8,
52:     /// Telemetry sensor payload type identifier.
53:     pub payload_id: u16,
54:     /// Microsecond clock counter ticks since flight controller boot.
55:     pub timestamp_ticks: u32,
56:     /// Borrowed slice containing the raw telemetry payload bytes.
57:     pub payload: &'a [u8],
58:     /// Checksum algorithm validated for this frame.
59:     pub checksum_type: DatChecksumType,
60: }
61: 
62: impl<'a> DatFrame<'a> {
63:     /// Parses a single `.DAT` frame from a borrowed byte slice with zero allocations.
64:     ///
65:     /// Validates the `0x55` magic byte, checks the minimum frame length, verifies
66:     /// the frame checksum (attempting CRC16 first with primary `0x3692` and fallback `0xFFFF`,
67:     /// then CRC32 if length $\ge 13$), and extracts the raw payload slice.
68:     ///
69:     /// # Errors
70:     /// * Returns `FlightReaderError::UnexpectedEof` if `frame_bytes` is empty.
71:     /// * Returns `FlightReaderError::SyncNotFound` if `frame_bytes[0] != 0x55`.
72:     /// * Returns `FlightReaderError::InvalidFrameLength` if declared length $< 11$.
73:     /// * Returns `FlightReaderError::TruncatedRecord` if `frame_bytes.len() < length`.
74:     /// * Returns `FlightReaderError::ChecksumMismatch` if checksum verification fails.
75:     pub fn parse(frame_bytes: &'a [u8]) -> Result<DatFrame<'a>> {
76:         if frame_bytes.is_empty() {
77:             return Err(FlightReaderError::UnexpectedEof);
78:         }
79: 
80:         if frame_bytes[0] != DAT_MAGIC {
81:             return Err(FlightReaderError::SyncNotFound);
82:         }
83: 
84:         if frame_bytes.len() < 2 {
85:             return Err(FlightReaderError::UnexpectedEof);
86:         }
87: 
88:         let length = frame_bytes[1];
89:         if (length as usize) < 11 {
90:             return Err(FlightReaderError::InvalidFrameLength {
91:                 length,
92:                 minimum: 11,
93:             });
94:         }
95: 
96:         if frame_bytes.len() < length as usize {
97:             return Err(FlightReaderError::TruncatedRecord {
98:                 expected: length as usize,
99:                 available: frame_bytes.len(),
100:             });
101:         }
102: 
103:         let frame_slice = &frame_bytes[..length as usize];
104: 
105:         // Determine checksum type and verify
106:         let (checksum_type, checksum_len) = match checksum::verify_crc16(frame_slice) {
107:             Ok(()) => (DatChecksumType::Crc16, 2),
108:             Err(crc16_err) => {
109:                 if (length as usize) >= 13 {
110:                     match checksum::verify_crc32(frame_slice) {
111:                         Ok(()) => (DatChecksumType::Crc32, 4),
112:                         Err(_) => return Err(crc16_err),
113:                     }
114:                 } else {
115:                     return Err(crc16_err);
116:                 }
117:             }
118:         };
119: 
120:         let sequence = frame_slice[2];
121:         let payload_id = u16::from_le_bytes([frame_slice[3], frame_slice[4]]);
122:         let timestamp_ticks = u32::from_le_bytes([
123:             frame_slice[5],
124:             frame_slice[6],
125:             frame_slice[7],
126:             frame_slice[8],
127:         ]);
128:         let payload = &frame_slice[HEADER_LEN..length as usize - checksum_len];
129: 
130:         Ok(DatFrame {
131:             magic: DAT_MAGIC,
132:             length,
133:             sequence,
134:             payload_id,
135:             timestamp_ticks,
136:             payload,
137:             checksum_type,
138:         })
139:     }
