## 9. Concrete Implementation Blueprint

### 9.1 `crates/flightreader-core/src/txt/record.rs`
```rust
//! DJI `.txt` flight log record stream demuxer and envelope parser.
//!
//! Provides zero-allocation framing and parsing for DJI `.txt` telemetry records
//! across format versions 1 through 14, supporting 1-byte and 2-byte length headers,
//! line-end delimiter (`0xFF`) validation, and robust stream resynchronization.

use std::borrow::Cow;
use byteorder::{ByteOrder, LittleEndian};

use crate::crypto::xor::descramble_record_to_vec;
use crate::error::{FlightReaderError, Result};
use crate::txt::header::TxtHeader;
use crate::txt::version::{DetailsLocation, ScrambleType, VersionCapabilities};

/// Framing delimiter sentinel byte separating consecutive records (`0xFF` / `255` decimal).
pub const RECORD_DELIMITER: u8 = 0xFF;

/// A zero-allocation borrowed view of a raw DJI `.txt` flight telemetry record envelope.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RawRecordEnvelope<'a> {
    /// Numerical record type identifier (e.g. 1 for OSD, 2 for Home).
    pub record_type: u8,
    /// Borrowed raw payload slice from the file stream.
    pub payload: &'a [u8],
}

impl<'a> RawRecordEnvelope<'a> {
    /// Constructs a new `RawRecordEnvelope` from borrowed fields.
    #[inline]
    pub const fn new(record_type: u8, payload: &'a [u8]) -> Self {
        Self {
            record_type,
            payload,
        }
    }

    /// Parses a single record envelope from the beginning of `input`.
    ///
    /// # Protocol Format
    /// - Byte 0: `record_type` (`u8`)
    /// - Bytes 1..=W: `length` (`u8` if `record_len_width == 1`, `u16_le` if `record_len_width == 2`)
    /// - Bytes (1+W)..((1+W)+L): `payload` (`L` bytes)
    /// - Byte (1+W)+L: Delimiter byte (must equal `0xFF`)
    ///
    /// Returns `Ok((envelope, total_consumed_bytes))`.
    pub fn parse(input: &'a [u8], record_len_width: usize) -> Result<(Self, usize)> {
        let header_size = 1 + record_len_width;
        if input.len() < header_size {
            return Err(FlightReaderError::UnexpectedEof);
        }

        let record_type = input[0];
        let payload_len = match record_len_width {
            1 => input[1] as usize,
            2 => LittleEndian::read_u16(&input[1..3]) as usize,
            other => {
                return Err(FlightReaderError::UnsupportedVersion {
                    version: other as u8,
                })
            }
        };

        let total_len = header_size + payload_len + 1;
        if input.len() < total_len {
            return Err(FlightReaderError::TruncatedRecord {
                expected: total_len,
                available: input.len(),
            });
        }

        let delimiter = input[header_size + payload_len];
        if delimiter != RECORD_DELIMITER {
            return Err(FlightReaderError::InvalidRecordDelimiter { found: delimiter });
        }

        let payload = &input[header_size..header_size + payload_len];
        Ok((Self { record_type, payload }, total_len))
    }

    /// De-scrambles this record payload using the cyclic XOR keystream engine (v7–v12).
    pub fn descramble_xor(&self) -> Result<Vec<u8>> {
        descramble_record_to_vec(self.payload, self.record_type)
    }

    /// Recovers plaintext payload bytes according to the format's scramble type.
    pub fn to_plaintext(&self, scramble_type: ScrambleType) -> Result<Cow<'a, [u8]>> {
        match scramble_type {
            ScrambleType::None => Ok(Cow::Borrowed(self.payload)),
            ScrambleType::Xor => {
                let plain = self.descramble_xor()?;
                Ok(Cow::Owned(plain))
            }
            ScrambleType::Aes => {
                // In v13/v14, records undergo XOR de-scrambling first
                let plain = self.descramble_xor()?;
                Ok(Cow::Owned(plain))
            }
        }
    }
}

/// Streaming zero-allocation iterator over DJI `.txt` binary flight records.
#[derive(Debug, Clone)]
pub struct RecordEnvelopeIterator<'a> {
    buffer: &'a [u8],
    current_offset: usize,
    end_offset: usize,
    capabilities: VersionCapabilities,
    header_offset: usize,
    resync: bool,
}

impl<'a> RecordEnvelopeIterator<'a> {
    /// Construct a new `RecordEnvelopeIterator` from a flight log buffer and parsed header.
    pub fn new(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
        let capabilities = header.capabilities()?;
        let header_offset = header.header_length as usize;

        let (current_offset, end_offset) = match capabilities.details_location {
            DetailsLocation::EndOfFile => {
                let end = (header.details_offset as usize).min(buffer.len());
                let start = header_offset.min(end);
                (start, end)
            }
            DetailsLocation::HeaderOffset => {
                let start = (header.details_offset as usize).min(buffer.len());
                (start, buffer.len())
            }
        };

        Ok(Self {
            buffer,
            current_offset,
            end_offset,
            capabilities,
            header_offset,
            resync: true,
        })
    }

    /// Construct an iterator over a raw record slice with known capabilities.
    pub fn from_slice(slice: &'a [u8], capabilities: VersionCapabilities) -> Self {
        Self {
            buffer: slice,
            current_offset: 0,
            end_offset: slice.len(),
            capabilities,
            header_offset: 0,
            resync: true,
        }
    }

    /// Sets whether stream resynchronization is enabled.
    pub fn with_resync(mut self, resync: bool) -> Self {
        self.resync = resync;
        self
    }

    /// Current cursor offset within `buffer`.
    #[inline]
    pub fn current_offset(&self) -> usize {
        self.current_offset
    }

    /// End offset bounding the record stream.
    #[inline]
    pub fn end_offset(&self) -> usize {
        self.end_offset
    }

    /// Header boundary offset.
    #[inline]
    pub fn header_offset(&self) -> usize {
        self.header_offset
    }

    /// Version capabilities for this record stream.
    #[inline]
    pub fn capabilities(&self) -> &VersionCapabilities {
        &self.capabilities
    }

    /// Returns unconsumed slice of the record stream.
    #[inline]
    pub fn remaining(&self) -> &'a [u8] {
        if self.current_offset >= self.end_offset {
            &[]
        } else {
            &self.buffer[self.current_offset..self.end_offset]
        }
    }
}

impl<'a> Iterator for RecordEnvelopeIterator<'a> {
    type Item = Result<RawRecordEnvelope<'a>>;

    fn next(&mut self) -> Option<Self::Item> {
        let record_len_width = self.capabilities.record_len_width;
        let header_size = 1 + record_len_width;

        while self.current_offset < self.end_offset {
            // Skip stray delimiter bytes between flight records
            if self.buffer[self.current_offset] == RECORD_DELIMITER {
                self.current_offset += 1;
                continue;
            }

            // Check if remaining slice can hold at least a record header
            if self.current_offset + header_size > self.end_offset {
                self.current_offset = self.end_offset;
                return None;
            }

            let slice = &self.buffer[self.current_offset..self.end_offset];
            match RawRecordEnvelope::parse(slice, record_len_width) {
                Ok((envelope, total_len)) => {
                    self.current_offset += total_len;
                    return Some(Ok(envelope));
                }
                Err(err) => {
                    if !self.resync {
                        self.current_offset = self.end_offset;
                        return Some(Err(err));
                    }

                    // Resynchronization mode: locate next plausible delimiter boundary
                    let search_slice = &self.buffer[self.current_offset + 1..self.end_offset];
                    if let Some(pos) = search_slice.iter().position(|&b| b == RECORD_DELIMITER) {
                        let candidate_start = self.current_offset + 1 + pos + 1;
                        self.current_offset = candidate_start.min(self.end_offset);
                    } else {
                        self.current_offset = self.end_offset;
                    }

                    return Some(Err(err));
                }
            }
        }

        None
    }
}
```

